PRAGMA foreign_keys=ON;
CREATE VIRTUAL TABLE search_index USING fts5(object_type UNINDEXED,object_id UNINDEXED,investigation_id UNINDEXED,title,body,aliases,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER search_investigation_insert AFTER INSERT ON investigations WHEN new.published_at IS NOT NULL BEGIN INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) VALUES('INVESTIGATION',new.id,new.id,new.title,new.summary,''); END;
CREATE TRIGGER search_investigation_update AFTER UPDATE OF title,summary,published_at ON investigations BEGIN DELETE FROM search_index WHERE object_type='INVESTIGATION' AND object_id=old.id; INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'INVESTIGATION',new.id,new.id,new.title,new.summary,'' WHERE new.published_at IS NOT NULL; END;
CREATE TRIGGER search_investigation_delete AFTER DELETE ON investigations BEGIN DELETE FROM search_index WHERE object_type='INVESTIGATION' AND object_id=old.id; END;
CREATE TRIGGER search_update_insert AFTER INSERT ON investigation_updates BEGIN INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) VALUES('UPDATE',new.id,new.investigation_id,COALESCE(new.title,''),new.content,new.type); END;
CREATE TRIGGER search_update_delete AFTER DELETE ON investigation_updates BEGIN DELETE FROM search_index WHERE object_type='UPDATE' AND object_id=old.id; END;
CREATE TRIGGER search_evidence_insert AFTER INSERT ON evidence BEGIN INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) VALUES('EVIDENCE',new.id,new.investigation_id,new.title,COALESCE(new.description,''),COALESCE(new.verification_state,'')); END;
CREATE TRIGGER search_evidence_update AFTER UPDATE OF title,description,verification_state ON evidence BEGIN DELETE FROM search_index WHERE object_type='EVIDENCE' AND object_id=old.id; INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) VALUES('EVIDENCE',new.id,new.investigation_id,new.title,COALESCE(new.description,''),COALESCE(new.verification_state,'')); END;
CREATE TRIGGER search_evidence_delete AFTER DELETE ON evidence BEGIN DELETE FROM search_index WHERE object_type='EVIDENCE' AND object_id=old.id; END;
CREATE TRIGGER search_entity_insert AFTER INSERT ON entities BEGIN INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) VALUES('ENTITY',new.id,NULL,new.canonical_name,COALESCE(new.description,''),''); END;
CREATE TRIGGER search_entity_update AFTER UPDATE OF canonical_name,description ON entities BEGIN DELETE FROM search_index WHERE object_type='ENTITY' AND object_id=old.id; INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'ENTITY',new.id,ie.investigation_id,new.canonical_name,COALESCE(new.description,''),COALESCE((SELECT group_concat(alias,' ') FROM entity_aliases WHERE entity_id=new.id),'') FROM (SELECT NULL investigation_id) x LEFT JOIN investigation_entities ie ON ie.entity_id=new.id; END;
CREATE TRIGGER search_entity_delete AFTER DELETE ON entities BEGIN DELETE FROM search_index WHERE object_type='ENTITY' AND object_id=old.id; END;
CREATE TRIGGER search_alias_insert AFTER INSERT ON entity_aliases BEGIN UPDATE search_index SET aliases=COALESCE((SELECT group_concat(alias,' ') FROM entity_aliases WHERE entity_id=new.entity_id),'') WHERE object_type='ENTITY' AND object_id=new.entity_id; END;
CREATE TRIGGER search_alias_update AFTER UPDATE OF alias,normalized_alias ON entity_aliases BEGIN UPDATE search_index SET aliases=COALESCE((SELECT group_concat(alias,' ') FROM entity_aliases WHERE entity_id=new.entity_id),'') WHERE object_type='ENTITY' AND object_id=new.entity_id; END;
CREATE TRIGGER search_alias_delete AFTER DELETE ON entity_aliases BEGIN UPDATE search_index SET aliases=COALESCE((SELECT group_concat(alias,' ') FROM entity_aliases WHERE entity_id=old.entity_id),'') WHERE object_type='ENTITY' AND object_id=old.entity_id; END;
INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'INVESTIGATION',id,id,title,summary,'' FROM investigations WHERE published_at IS NOT NULL;
INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'UPDATE',id,investigation_id,COALESCE(title,''),content,type FROM investigation_updates;
INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'EVIDENCE',id,investigation_id,title,COALESCE(description,''),COALESCE(verification_state,'') FROM evidence;
INSERT INTO search_index(object_type,object_id,investigation_id,title,body,aliases) SELECT 'ENTITY',e.id,ie.investigation_id,e.canonical_name,COALESCE(e.description,''),COALESCE((SELECT group_concat(alias,' ') FROM entity_aliases a WHERE a.entity_id=e.id),'') FROM entities e LEFT JOIN investigation_entities ie ON ie.entity_id=e.id;
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES('0002_search',unixepoch()*1000);
